// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;

    function setUp() public { c = new ReentrancyDAO(); }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, 1e18);

        // honest third-party deposit that the re-entrant attacker must not be able to steal
        address user = address(0xBEEF);
        vm.deal(user, amount);
        vm.prank(user);
        c.deposit{value: amount}();

        // adversarial re-entrant counterparty
        Attacker atk = new Attacker(c);
        vm.deal(address(atk), amount);
        vm.prank(address(atk));
        c.deposit{value: amount}();

        // attacker triggers re-entrant withdrawals
        atk.attack();

        // General rule: after any re-entrancy attempt, only the attacker's own credit may be
        // withdrawn once; the honest user's deposit must still be held by the contract.
        assertTrue(address(c).balance == amount);
    }
}

contract Attacker {
    ReentrancyDAO c;

    constructor(ReentrancyDAO _c) { c = _c; }

    function attack() external {
        c.withdrawAll();
    }

    receive() external payable {
        // re-enter withdrawAll while credit has not yet been reset
        if (address(c).balance >= address(this).balance) {
            try c.withdrawAll() {} catch {}
        }
    }
}
